import {drawEnergy} from './energy-labs.mjs';
export function drawAdvanced(id,m,H){const energy=drawEnergy(id,m,H);if(energy)return energy;const {ctx,text,line,box,circle,arrow,grid,wave,bar,colors,green,white,muted,t}=H,TAU=Math.PI*2;
if(id==='resonance'){
 const x=255+m.x*1300;box(65,185,25,195,'#405d55',muted);line([[65,385],[485,385]],muted,4);const coil=[[90,290]];for(let j=1;j<=24;j++)coil.push([90+(x-145)*j/24,290+(j%2?19:-19)]);coil.push([x-55,290]);line(coil,colors[1],3);box(x-55,245,110,85,'#547662',green);circle(x-32,350,18,'#182d34',white);circle(x+32,350,18,'#182d34',white);arrow(x,220,55*Math.sin(TAU*m.a*t),0,colors[2]);text('MASA + RESORTE + AMORTIGUAMIENTO',265,440,14,muted,'center');
 grid(550,100,390,290);const pts=[];for(let j=0;j<=200;j++){const r=.2+j/200*1.8,g=1/Math.hypot(1-r*r,2*m.b*r);pts.push([550+j/200*390,390-g/10*270])}line(pts,colors[0],3);circle(550+(m.a-.2)/1.8*390,390-m.gain/10*270,7,green,null);text('AMPLIFICACIÓN M',550,80,17,colors[0]);text('r = 0,2',550,425,15,muted);text('2,0',940,425,15,muted,'right');text('0',540,395,14,muted,'right');text('10',540,125,14,muted,'right');return ['Respuesta estacionaria','Resorte','Fuerza periódica'];
}
if(id==='standing'){
 grid(70,100,860,310);const pts=[];for(let i=0;i<=400;i++){const u=i/400;pts.push([80+840*u,255-95*Math.sin(m.a*Math.PI*u)*Math.cos(m.phase)])}for(const sign of [-1,1]){const envelope=[];for(let i=0;i<=300;i++){const u=i/300;envelope.push([80+840*u,255+sign*95*Math.abs(Math.sin(m.a*Math.PI*u))])}line(envelope,'#46666a',1,[4,5])}line(pts,colors[0],5);for(let i=0;i<=m.a;i++){circle(80+840*i/m.a,255,7,colors[1],null);text(i===0||i===m.a?'FIJO':'NODO',80+840*i/m.a,430,14,colors[1],'center')}box(65,205,15,100,'#6c8779',white);box(920,205,15,100,'#6c8779',white);text('L = 1 m · modo '+m.a,500,475,21,green,'center');return ['Cuerda','Nodos inmóviles'];
}
if(id==='phasesequence'){
 const cx=250,cy=260;circle(cx,cy,157,'#29444b','#78968f',4);circle(cx,cy,120,'#102127','#526c67');for(let i=0;i<6;i++){const ang=i*TAU/6,ci=[0,2,1,0,2,1][i];ctx.save();ctx.translate(cx+138*Math.cos(ang),cy+138*Math.sin(ang));ctx.rotate(ang);box(-18,-25,36,50,'#493e30',colors[ci]);for(let j=-12;j<=12;j+=6)line([[j,-23],[j,23]],colors[ci]);ctx.restore()}const r=100*m.b;arrow(cx,cy,r*Math.cos(m.angle),-r*Math.sin(m.angle),green,7);circle(cx,cy,12,white,null);ctx.beginPath();ctx.arc(cx,cy,185,.15,Math.PI*1.65);ctx.strokeStyle=green;ctx.setLineDash([9,8]);ctx.stroke();ctx.setLineDash([]);text(m.on?'ABC →':'ACB ←',cx,480,32,green,'center');grid(510,110,430,280);for(let i=0;i<3;i++){const order=m.on?i:[0,2,1][i];wave(u=>m.b*Math.sin(TAU*u*2+TAU*m.a*t/100-order*TAU/3),colors[i],510,110,430,280)}text('SECUENCIA '+(m.on?'A → B → C':'A → C → B'),510,445,22,white);return ['Fase A','Fase B','Fase C'];
}
if(id==='cavitation'){
 const p=[[70,170],[300,170],[400,215],[650,215],[750,170],[940,170],[940,350],[750,350],[650,305],[400,305],[300,350],[70,350]];ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();ctx.fillStyle='#204853';ctx.fill();ctx.strokeStyle=colors[0];ctx.lineWidth=3;ctx.stroke();const amount=m.margin<0?Math.min(30,5+Math.abs(m.margin)*2):0;for(let i=0;i<amount;i++){const x=410+((i*37+t*100)%230),y=236+(Math.sin(i*7+t)*.5+.5)*48;const rr=3+5*(Math.sin(t*4+i)**2);circle(x,y,rr,'#7aa7ac88',colors[0],1)}for(let i=0;i<16;i++){const x=75+((i*54+t*80)%860);circle(x,260,2,colors[0],null)}text('p local = '+m.a.toFixed(1)+' kPa abs',500,135,24,colors[1],'center');text('pvapor = '+m.vapor.toFixed(2)+' kPa',500,400,22,white,'center');text(m.margin<0?'CONDICIÓN FAVORABLE A VAPOR':'MARGEN POSITIVO',500,465,25,m.margin<0?colors[2]:green,'center');return ['Agua / cavidades de vapor','Presión local'];
}
if(id==='airlogic'){
 for(const [y,active,name,p]of [[170,m.A,'A',m.a],[350,m.B,'B',m.b]]){box(90,y-45,160,90,active?'#395c48':'#263e43',active?green:muted);text(name+' = '+Number(active),170,y-5,26,active?green:white,'center');text(p.toFixed(1)+' bar',170,y+25,19,muted,'center');line([[250,y],[400,y],[400,y===170?225:295],[470,y===170?225:295]],active?colors[0]:'#36545a',6)}box(470,195,170,130,'#3e4f42',green,12);text(m.on?'AND':'OR',555,267,38,green,'center');line([[640,260],[795,260]],m.Y?colors[0]:'#36545a',7);circle(840,260,45,m.Y?'#77ac66':'#273b40',m.Y?green:muted,3);text('Y = '+Number(m.Y),840,350,27,m.Y?green:white,'center');text('UMBRAL DE ENTRADA: 3 bar',500,455,22,muted,'center');return ['Señal activa','Entrada B'];
}
if(id==='robotarm'){
 const project=(x,y,z=0)=>[460+.75*x-.48*y,330+.23*x+.38*y-z];
 // Fixed-scale isometric workspace; the two joint angles drive both geometry and coordinates.
 for(let v=-350;v<=350;v+=50){line([project(v,-350),project(v,350)],'#294448',1);line([project(-350,v),project(350,v)],'#294448',1)}
 function prism(points,z,h,top,side){const p=points.map(([x,y])=>project(x,y,z)),q=points.map(([x,y])=>project(x,y,z+h));for(let i=0;i<points.length;i++){const j=(i+1)%points.length;ctx.beginPath();ctx.moveTo(...p[i]);ctx.lineTo(...p[j]);ctx.lineTo(...q[j]);ctx.lineTo(...q[i]);ctx.closePath();ctx.fillStyle=side;ctx.fill()}ctx.beginPath();q.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v));ctx.closePath();ctx.fillStyle=top;ctx.fill();ctx.strokeStyle='#b5c6b0';ctx.lineWidth=1.4;ctx.stroke()}
 prism([[-65,-65],[65,-65],[65,65],[-65,65]],0,18,'#58736b','#2b454a');prism([[-29,-29],[29,-29],[29,29],[-29,29]],18,45,'#7c9b86','#46665e');
 const segment=(from,to,z,col)=>{const dx=to[0]-from[0],dy=to[1]-from[1],len=Math.hypot(dx,dy),nx=-dy/len*17,ny=dx/len*17;prism([[from[0]+nx,from[1]+ny],[to[0]+nx,to[1]+ny],[to[0]-nx,to[1]-ny],[from[0]-nx,from[1]-ny]],z,18,col,'#395a57');for(let i=1;i<9;i++){const p=project(from[0]+dx*i/10,from[1]+dy*i/10,z+19);circle(...p,2,'#c4d5b5',null)}};
 segment([0,0],m.elbow,63,'#88b8aa');segment(m.elbow,m.tip,83,'#c0cc91');
 for(const [j,z]of [[[0,0],82],[m.elbow,103],[m.tip,104]]){const p=project(...j,z);ctx.beginPath();ctx.ellipse(...p,21,11,0,0,TAU);ctx.fillStyle='#203e43';ctx.fill();ctx.strokeStyle=colors[0];ctx.stroke();for(let i=0;i<8;i++){const a=i*TAU/8;circle(p[0]+16*Math.cos(a),p[1]+8*Math.sin(a),1.6,white,null)}}
 const tip=project(...m.tip,104),ground=project(...m.tip);line([tip,ground],colors[1],1,[5,5]);circle(...ground,6,colors[1],null);for(let v=0;v<2;v++){const off=v?8:-8;line([[tip[0]+off,tip[1]],[tip[0]+off,tip[1]+23],[tip[0]+off*.4,tip[1]+23]],white,4)}
 text('θ₁ = '+m.a+'°',55,105,24,colors[0]);text('θ₂ = '+m.b+'°',55,145,24,colors[1]);text('L₁ 200 mm · L₂ 150 mm',55,185,17,muted);text('CINEMÁTICA DIRECTA · PLANO HORIZONTAL',500,485,18,green,'center');return ['Primer eslabón','Herramienta / segundo eslabón'];
}
return null;
}
